<?php declare(strict_types=1);
namespace FMonitor2\PilotHttp;

final class ProductionConstructionControlRenderer
{
    public function render(HttpUser $user,array $objects):string
    {
        $e=[PilotView::class,'e'];$count=\count($objects);$rows='';
        foreach($objects as$o){$id=$e($o['id']);$engineerId=(int)($o['controlEngineer']['userId']??0);$completed=(bool)($o['completed']??false);$last=(string)($o['lastChecklistActivityAt']??'');$activity=$last===''?'Инспекций ещё не было':self::activityLabel($last);$engineer=(string)($o['controlEngineer']['fullName']??'Инженер не назначен');$search=\mb_strtolower($o['address'].' '.$o['registrationNumber']);$rows.='<tr class="fm2-control-row" data-control-row data-object-id="'.$id.'" data-engineer-id="'.$engineerId.'" data-completed="'.($completed?'true':'false').'" data-search="'.$e($search).'"><td class="fm2-control-object"><a class="fm2-control-link" href="/pilot/construction-control/objects/'.$id.'/checklist"><span class="fm2-control-address">'.$e($o['address']).'</span><span class="fm2-control-reg"><strong class="fm2-control-entrance">Подъезд '.$e($o['entrance']).'</strong><span>Рег. № '.$e($o['registrationNumber']).'</span></span></a></td><td data-label="Последняя инспекция"><span class="fm2-activity-line"><span class="fm2-local-sync" data-local-sync role="img" aria-label="Синхронизировано"></span><span class="fm2-activity'.($last===''?' fm2-activity--never':'').'">'.$e($activity).'</span></span></td><td data-label="Инженер"><span class="fm2-cell-main">'.$e($engineer).'</span></td><td class="fm2-row-action"><span aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m9 5 7 7-7 7"/></svg></span></td></tr>';}
        $body='<section class="fm2-control-queue" data-control-queue data-user-id="'.$user->id.'"><header class="fm2-control-header"><h1>Стройконтроль</h1><span class="fm2-result-count" data-result-count>'.$count.' объектов</span></header><div class="fm2-control-tools"><label class="shlz-field fm2-control-search"><span class="shlz-field__label">Поиск объектов</span><span class="shlz-field__control"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6"/><path d="m16 16 4 4"/></svg><input class="shlz-input" type="search" autocomplete="off" placeholder="Адрес или регистрационный номер" data-control-search></span></label><div class="fm2-control-filters"><fieldset class="shlz-segment shlz-segment--lg"><legend class="shlz-visually-hidden">Принадлежность объектов</legend><label class="shlz-segment__option"><input class="shlz-segment__input" type="radio" name="ownership" value="mine" checked><span class="shlz-segment__label">Мои</span></label><label class="shlz-segment__option"><input class="shlz-segment__input" type="radio" name="ownership" value="all"><span class="shlz-segment__label">Все</span></label></fieldset><label class="shlz-switch fm2-completed-switch"><input class="shlz-switch__input" type="checkbox" role="switch" data-show-completed><span><span class="fm2-completed-prefix">Показывать </span>завершённые</span></label></div></div><div class="fm2-control-surface"><div class="fm2-table-wrap"><table class="shlz-table fm2-control-table"><thead><tr><th>Объект</th><th>Последняя инспекция</th><th>Инженер</th><th></th></tr></thead><tbody>'.$rows.'</tbody></table></div><div class="shlz-empty-state fm2-control-empty" data-control-empty hidden><strong>Объекты не найдены</strong><p>Измените запрос или параметры отображения.</p><button class="shlz-button" type="button" data-clear-filters>Сбросить фильтры</button></div><footer class="fm2-control-footer"><span data-list-summary>Показано '.$count.'</span><span>Сначала — без инспекций и давно не проверявшиеся</span></footer></div></section>';
        return \str_replace('</body>','<script src="/pilot/assets/control-queue.js?v=20260829-4" defer></script></body>',PilotView::document($user,'Стройконтроль','Стройконтроль','',$body));
    }
    private static function activityLabel(string $value):string{try{$then=new \DateTimeImmutable($value);$now=new \DateTimeImmutable('now',$then->getTimezone());$days=(int)$then->setTime(0,0)->diff($now->setTime(0,0))->format('%r%a');if($days<=0)return 'Сегодня, '.$then->format('H:i');if($days===1)return 'Вчера, '.$then->format('H:i');return $days.' '.self::daysWord($days).' назад';}catch(\Throwable){return 'Давно не обновлялся';}}
    private static function daysWord(int $days):string{$n=$days%100;if($n>=11&&$n<=14)return'дней';return match($days%10){1=>'день',2,3,4=>'дня',default=>'дней'};}
}
